const CL_KINDS = {
    feature:  { label: 'قابلیت‌های جدید', icon: 'ph-sparkle',       color: 'var(--mv-blue-ink)' },
    fix:      { label: 'رفع اشکال',        icon: 'ph-bug-beetle',    color: 'var(--mv-red-ink)' },
    improve:  { label: 'بهبودها',          icon: 'ph-trend-up',      color: 'var(--mv-green-ink)' },
    security: { label: 'امنیت',            icon: 'ph-shield-check',  color: 'var(--mv-orange-ink)' },
};

let clExpanded = {};   // version -> bool

function clEsc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
    }[c]));
}

/**
 * Details are written with paragraphs and **bold** — they were being escaped whole, so the
 * asterisks showed and every blank line collapsed. Only these two forms are understood, and
 * everything else stays escaped: a changelog is app-authored text, but it is still text.
 */
function clDetail(text) {
    return String(text || '')
        .split(/\n\s*\n/)
        .map(par => '<p>' + clEsc(par.trim())
            .replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>')
            .replace(/\n/g, '<br>')
            .replace(/«([^»]+)»/g, '«<span class="cl-q">$1</span>»') + '</p>')
        .join('');
}

function clItemHtml(item) {
    const text = typeof item === 'string' ? item : item.text;
    const detail = typeof item === 'string' ? '' : (item.detail || '');
    return `
      <div class="mv-form-row is-stack cl-item">
        <span class="cl-item-text">${clEsc(text)}</span>
        ${detail ? `<div class="cl-item-detail">${clDetail(detail)}</div>` : ''}
      </div>`;
}

/** Which version the pane is showing. Defaults to the newest, which is what people came for. */
let clCurrent = null;

window.clGo = function (version) {
    const entry = CHANGELOG.find(e => e.version === version) || CHANGELOG[0];
    clCurrent = entry.version;
    const root = document.getElementById('changelog-root');
    if (!root) return;
    root.querySelectorAll('.mv-side-item[data-cl-ver]').forEach(b => {
        b.classList.toggle('active', b.getAttribute('data-cl-ver') === clCurrent);
    });
    const title = document.getElementById('cl-title');
    if (title) title.textContent = 'نسخهٔ ' + entry.version;
    const back = document.getElementById('cl-back');
    if (back) back.disabled = CHANGELOG[0].version === clCurrent;
    const pane = root.querySelector('.mv-pane');
    if (pane) pane.classList.toggle('is-home', CHANGELOG[0].version === clCurrent);
    clRenderVersion(entry);
    const sc = root.querySelector('.mv-pane-scroll');
    if (sc) sc.scrollTop = 0;
};

function clRenderVersion(entry) {
    const host = document.getElementById('cl-body');
    if (!host) return;
    const isLatest = CHANGELOG[0].version === entry.version;
    const count = entry.sections.reduce((a, s) => a + s.items.length, 0);
    host.innerHTML = `
    <div class="mv-form">
      <div class="mv-form-section is-wide">
        <div class="mv-form-group">
          <div class="mv-status-head">
            <span class="mv-side-tile" style="--tint:var(--mv-blue)"><i class="ph-fill ${isLatest ? 'ph-sparkle' : 'ph-tag'}"></i></span>
            <div class="mv-sh-text">
              <h2>نسخهٔ <span dir="ltr" class="cl-num">${clEsc(entry.version)}</span>${isLatest ? ' <span class="mv-pill is-ok">جدید</span>' : ''}</h2>
              <p>${clEsc(entry.title || '')}</p>
            </div>
            <div class="mv-sh-end cl-meta">
              <span class="cl-num">${clEsc(entry.date || '')}</span>
              <span class="cl-num">${count.toLocaleString('fa-IR')} مورد</span>
            </div>
          </div>
        </div>
      </div>

      ${entry.sections.map(sec => {
        const k = CL_KINDS[sec.kind] || CL_KINDS.improve;
        return `
        <div class="mv-form-section is-wide">
          <div class="mv-form-header cl-kind" style="color:${k.color}">
            <i class="ph-bold ${k.icon}"></i><b>${clEsc(k.label)}</b>
            <span class="cl-num">${sec.items.length.toLocaleString('fa-IR')}</span>
          </div>
          <div class="mv-form-group cl-entries">${sec.items.map(clItemHtml).join('')}</div>
        </div>`;
      }).join('')}
    </div>`;
}

/**
 * «لیست تغییرات» on the page kit.
 *
 * It was one long scroll of accordions: to read version 1.2.1 you scrolled past everything
 * newer, and with eighty-odd entries in the current release that is a lot of scrolling past.
 * Each version is its own page now, and the sidebar is the index — with the kit's own search,
 * so a word from any release title finds it.
 */
window.renderChangelogTab = function () {
    let root = document.getElementById('changelog-root');
    if (!root) {
        root = document.createElement('div');
        root.id = 'changelog-root';
        // NO flex-col here: this root is a .mv-split, which is a flex ROW. The two together
        // stack the sidebar on top of the page — the bug the netdiag page shipped with.
        root.className = 'cl-split mv-split';
        root.dir = 'rtl';
        const wrap = document.getElementById('editor-content-wrap');
        if (wrap) wrap.appendChild(root);
    }
    root.style.display = 'flex';
    if (typeof updateBreadcrumb === 'function') updateBreadcrumb('لیست تغییرات');

    if (!root.dataset.built) {
        root.innerHTML = CL_SHELL + CL_STYLE;
        root.dataset.built = '1';
        root.querySelectorAll('.mv-side-item[data-cl-ver]').forEach(b => {
            b.addEventListener('click', () => window.clGo(b.getAttribute('data-cl-ver')));
        });
        const back = document.getElementById('cl-back');
        if (back) back.addEventListener('click', () => window.clGo(CHANGELOG[0].version));
    }
    window.clGo(clCurrent || CHANGELOG[0].version);
};

const CL_SHELL = `
  <aside class="mv-side" id="changelog-sidebar" aria-label="نسخه‌ها">
    <div class="mv-side-top"></div>
    <label class="mv-side-search">
      <i class="ph ph-magnifying-glass"></i>
      <input type="search" placeholder="جست‌وجو در نسخه‌ها" aria-label="جست‌وجو در نسخه‌ها" data-mv-side-search />
    </label>
    <nav class="mv-side-list custom-scrollbar">
      <div class="mv-side-group">
        <div class="mv-side-head">نسخه‌ها</div>
        ${CHANGELOG.map((e, i) => `
        <button type="button" class="mv-side-item" data-cl-ver="${clEsc(e.version)}" data-kw="${clEsc(e.title || '')} ${clEsc(e.date || '')}">
          <span class="mv-side-tile" style="--tint:${i === 0 ? 'var(--mv-blue)' : 'var(--mv-gray)'}"><i class="ph-fill ${i === 0 ? 'ph-sparkle' : 'ph-tag'}"></i></span>
          <span dir="ltr" class="cl-num">${clEsc(e.version)}</span>
        </button>`).join('')}
      </div>
      <div class="mv-side-empty" data-mv-side-empty hidden>نسخه‌ای با این نام نیست.</div>
    </nav>
  </aside>

  <section class="mv-pane">
    <header class="mv-pane-bar">
      <div class="mv-pane-nav" role="group" aria-label="پیمایش نسخه‌ها">
        <button type="button" id="cl-back" aria-label="تازه‌ترین نسخه" title="تازه‌ترین نسخه" disabled><i class="ph-bold ph-caret-right"></i></button>
      </div>
      <h1 class="mv-pane-title" id="cl-title">لیست تغییرات</h1>
    </header>
    <div class="mv-pane-scroll custom-scrollbar"><div id="cl-body"></div></div>
  </section>`;

const CL_STYLE = `
<style id="cl-kit-css">
  .cl-split { height:100%; min-height:0; flex:1; min-width:0; }
  /* THE PAGE USES THE WINDOW IT IS GIVEN.
     .mv-form is capped at 760px and centred — right for a settings form, wrong for a page whose
     whole job is reading. The engine pages undo it inside .mv-eng-sec; this page has no sections
     of that kind, so it says it itself, and the kit's own column rules then spread the entries
     into two or three modules as the window grows. */
  .cl-split .mv-form { max-width:none; }
  .cl-split .cl-num { font-family:var(--mv-font-tech); font-variant-numeric:tabular-nums; }
  .cl-split .cl-meta { display:flex; flex-direction:column; align-items:flex-end; gap:2px;
    font-size:11px; color:var(--mv-label-3); }
  .cl-split .cl-kind { display:flex; align-items:center; gap:7px; }
  .cl-split .cl-kind i { font-size:14px; }
  .cl-split .cl-kind .cl-num { margin-inline-start:auto; color:var(--mv-label-3); font-weight:600; }
  /* An entry is a headline and, when it has one, the reasoning under it. The reasoning is the
     part that was unreadable before: escaped whole, so the asterisks showed and the paragraphs
     ran together into one block. */
  /* ENTRIES FLOW LIKE A NEWSPAPER, NOT AS ROWS OF EQUAL-HEIGHT CELLS.
     The form kit lays a wide group out as a wrapping flex, which is right for controls and wrong
     for prose: entries differ wildly in length, so each row grew to its tallest member and left
     ragged gaps under the short ones. Real CSS columns pack them, and each entry becomes its own
     card so the group's hairlines are not needed.

     The selector has to out-specify the kit's own .mv-form-section.is-wide > .mv-form-group,
     which is (0,3,0) — a plainer one silently lost and the flex rows came back. And no
     backticks in here: this whole stylesheet lives in a template literal. */
  .cl-split .mv-form-section.is-wide > .cl-entries {
    display:block; padding:0; overflow:visible;
    background:none; box-shadow:none;
    columns:22rem; column-gap:12px;
  }
  .cl-split .cl-entries > .cl-item {
    break-inside:avoid; margin:0 0 12px; width:100%;
    border-radius:12px; background:var(--mv-group);
    box-shadow:inset 0 0 0 var(--mv-hl) var(--mv-group-edge);
  }
  /* …and none of the automatic separators the group would otherwise draw between rows. */
  .cl-split .cl-entries > .cl-item + .cl-item { border-top:0; }
  .cl-split .cl-item { flex-direction:column; align-items:flex-start; gap:5px; padding:11px 14px; }
  .cl-split .cl-item-text { font-size:12.5px; font-weight:650; line-height:1.85; }
  .cl-split .cl-item-detail { font-size:11.5px; line-height:2.05; color:var(--mv-label-2); }
  .cl-split .cl-item-detail p { margin:0 0 7px; }
  .cl-split .cl-item-detail p:last-child { margin-bottom:0; }
  .cl-split .cl-item-detail b { color:var(--mv-label); font-weight:700; }
  .cl-split .cl-q { color:var(--mv-label); }
</style>`;
/**
 * Stamp the sidebar badge with the real version.
 *
 * It used to be typed into index.html by hand — the badge said v1.2.2 and its tooltip said
 * ۱.۲.۰ while the app was on something else again, because three places had to be edited
 * and only one ever was. CHANGELOG[0] is the same source the About panel reads, so there is
 * now one number in one file.
 */
(function stampVersionBadge() {
    const apply = () => {
        const el = document.getElementById('app-version-badge');
        const top = CHANGELOG[0];
        if (!el || !top || !top.version) return;
        const fa = String(top.version).replace(/[0-9]/g, (d) => '۰۱۲۳۴۵۶۷۸۹'[d]);
        el.textContent = 'v' + top.version;
        el.setAttribute('title', el.getAttribute('title').replace(/شما [۰-۹.]+ می‌باشد/, 'شما ' + fa + ' می‌باشد'));
    };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply, { once: true });
    else apply();
})();

window.openChangelogTab = function () {
    const existing = tabs.find(t => t.type === 'changelog');
    if (existing) { switchTab(existing.id); return; }

    const id = 'tab_' + Date.now();
    tabs.push({
        id, isp: 'لیست تغییرات', state: 'done', type: 'changelog',
        total: 0, tested: 0, alive: 0, dead: 0, results: [], settings: {},
    });
    switchTab(id);

    const btnScan = document.getElementById('btn-tab-scan');
    if (btnScan) btnScan.click();
};
